  for _, name in ipairs({ "SetupParam", "OnSetupLayer" }) do
    local f = _G[name]
    if type(f) == "function" then
      _G[name] = function(...)
        return BBT_WithCampaignInfo(f, ...)
      end
    end
  end
end

