-- ===== EVT bb_tournament top mode selector BEGIN =====
-- BattleBayDeluxe bb_tournament, top menu part: this menu's side of the Campaña / Torneo mode selector.
-- Appended after bbt_top.lua in graft.toml's order: the parts share one chunk and its locals.
BattleBayDeluxe = type(BattleBayDeluxe) == "table" and BattleBayDeluxe or {}

-- ------------------------------------------------------------------------------------------------ the mode selector
-- (bbt_mode.lua draws it; this menu's side: «Torneo» lit while the bracket / its panel is up)

-- the team grid (enjoy_team_select_menu) seen open, then closed: what the grid left for this menu. Only for a grid
-- this file did not open itself (BBT_NewRun shows its own bracket): the header's «Torneo» with a run (parameter
-- evt_bbd_mode_go_tournament) = the Torneo here; a tournament started in it = its bracket; an armed leftover disarmed.
BBT_MODE_P_GO_T = 3937328500
function BBT_ModeAfterGrid()
  local S = BattleBayDeluxe.TournamentState
  local exists = funcLuaMenuCommand(2231168902, 786045682 --[[enjoy_team_select_menu]]) == true
  if exists then
    if not S.grid_seen then
      S.grid_seen = true
      S.grid_own = S.newrun == true
      S.grid_active = BBT_Info().active == true
    end
    return
  end
  if not S.grid_seen then
    return
  end
  S.grid_seen = false
  if S.grid_own then
    return
  end
  if VRFW_Param.Has(BBT_MODE_P_GO_T) then
    VRFW_Param.Clear(BBT_MODE_P_GO_T)
    S.after_grid, S.frames_after = "tournament", 0
    BBT_Log("grid closed: the Torneo asked from its header")
    return
  end
  local info = BBT_Info()
  if info.active and not S.grid_active then
    S.after_grid, S.frames_after = "bracket", 0
    BBT_Log("grid closed: a tournament started in it, its bracket")
  elseif info.armed then
    BBT_Call(BattleBayDeluxe.Tournament.DISARM)
    pcall(funcLuaCommand, BattleBayDeluxe.Tournament.RULE_SELECT, "")
  end
end

-- what waits for the menu's focus after a grid / a mode switch
function BBT_ModeAfterStep()
  local S = BattleBayDeluxe.TournamentState
  if S.after_grid == nil or S.co ~= nil or S.open or S.entry then
    return
  end
  S.frames_after = (S.frames_after or 0) + 1
  if S.frames_after > 600 then
    BBT_Log("mode: gave up waiting for the menu:", S.after_grid)
    S.after_grid = nil
    return
  end
  if S.frames_after < 6 or not BattleBayDeluxe.TournamentHost.ready() or funcLuaCommand(1215256347) == true
    or funcLuaMenuCommand(2231168902, BattleBayDeluxe.Tournament.SUB_WINDOW) == true then
    return
  end
  local what = S.after_grid
  S.after_grid = nil
  if what == "bracket" then
    if BBT_Info().fmt == 2 then
      S.co = coroutine.create(BBT_LeagueHub)
    else
      BBT_Open(BBT_EntryPage())
    end
  elseif what == "tournament" or what == "campaign" then
    BBT_DecideCampaignRow(what)
  end
end

-- bbt_mode.lua's Step hook in this menu: the grid watch, the waiting switch. The selector is never shown here (owner
-- 2026-10-13: only on the team-select grid before a run starts; a Torneo up here is a run in progress): kept hidden
function BBT_ModeTopStep()
  if BattleBayDeluxe.TournamentHost.name ~= "bb_stadium_top_menu" then
    return
  end
  local S = BattleBayDeluxe.TournamentState
  BBT_ModeAfterGrid()
  BBT_ModeAfterStep()
  -- 1.5.57: the selector's layers are no longer in this menu (the grid's own only): nothing drawn here
  BBT_ModePoll(false)   -- keeps the key / click edges current
end

-- 1.5.57 diagnosis (the white Battle Bay top menu of 2026-10-13: the menu past the engine's layer instance limit never
-- finished opening). Once per opening, BBT_SETUP_FRAMES Steps after OnInit: the instances the engine created of each
-- overlay pool (CMND_GET_CREATE_LAYER_NUM) against the menu file's counts, whether the background
-- (mainmenu90_00_background) is open and whether the screen is still covered by a fade (2259183189). A short pool
-- or «covered true» = the menu is still too big.
BBT_SETUP_FRAMES = 180
function BBT_SetupCheck()
  if BattleBayDeluxe.TournamentHost.name ~= "bb_stadium_top_menu" then
    return
  end
  local parts, short = {}, 0
  for k, n in pairs(BattleBayDeluxe.Tournament.N) do
    local got = funcLuaMenuCommand(1175615627, BattleBayDeluxe.Tournament.L[k])
    got = type(got) == "number" and got or -1
    if got < n then
      short = short + 1
    end
    parts[#parts + 1] = string.format("%s %d/%d", k, got, n)
  end
  table.sort(parts)
  local bg = funcLuaMenuCommand(2640875187, 367379312 --[[mainmenu90_00_background]], 0)
  local covered = funcLuaCommand(2259183189) == true
  BBT_Log(string.format("top menu setup: %s; background open %s, covered %s (%s)", table.concat(parts, ", "),
    tostring(bg), tostring(covered), (short > 0 or covered) and "STUCK? pools short or screen covered" or "ok"))
end
-- ===== EVT bb_tournament top mode selector END =====

-- ===== EVT bb_tournament top wraps BEGIN =====
-- BattleBayDeluxe bb_tournament, top menu part: the wraps of the menu's engine callbacks.
-- Appended after bbt_top.lua in graft.toml's order: the parts share one chunk and its locals.
BattleBayDeluxe = type(BattleBayDeluxe) == "table" and BattleBayDeluxe or {}

-- ------------------------------------------------------------------------------------------------ wraps

do
  local init = OnInit
  function OnInit(...)
    BattleBayDeluxe.TournamentState.setup_frames = 0
    local ok, done = pcall(BBT_Sync)
    if not ok then
      BBT_Log("sync error", tostring(done))
    elseif not done then
      BattleBayDeluxe.TournamentState.sync, BattleBayDeluxe.TournamentState.sync_frames = true, 0   -- the scripts were busy: again from Step
    end
    -- the top bar's «Battle Bay» group row «Torneo» (content\menus\top_bar.toml): the title's Estadio BB request with
    -- the step bb_tournament; answered here: the «Campaña» row decided in Torneo mode once the list is ready (Step)
    if BattleBayDeluxe.TournamentHost.step ~= nil and type(VRFW_TopBarStep) == "function" then
      local oks, go = pcall(VRFW_TopBarStep, BattleBayDeluxe.TournamentHost.step)
      if oks and go then
        BattleBayDeluxe.TournamentState.step, BattleBayDeluxe.TournamentState.frames, BattleBayDeluxe.TournamentState.want = true, 0, false
        BBT_Log("top bar step: the Campaña row in Torneo mode")
      end
    end
    return init(...)
  end

  local decide = OnDecideFocus
  function OnDecideFocus(a1, a2, ...)
    if BattleBayDeluxe.TournamentState.open then
      -- 1.37.0: a decide on another layer (the menu's own focus came back over the anchor) is the overlay's Enter too
      if a1 ~= BattleBayDeluxe.Tournament.ANCHOR then
        if BattleBayDeluxe.TournamentState.stray_decide ~= a1 then
          BattleBayDeluxe.TournamentState.stray_decide = a1
          BBT_Log("overlay keys: decide on layer " .. tostring(a1) .. ": taken as the overlay's Enter, the anchor focused")
        end
        BBT_FocusAnchor()
      end
      BBT_OnEnter()
      return 1
    end
    -- 1.5.47: the «Campaña» row opens the Campaña screen in Torneo mode when a tournament runs (or ended, not shown
    -- yet) or the top bar / the header asked for the Torneo; else the retail Campaña (its header switches there)
    if (a1 == BattleBayDeluxe.Tournament.LIST_MID or a1 == BattleBayDeluxe.Tournament.LIST_SMALL) and BattleBayDeluxe.TournamentHost.name == "bb_stadium_top_menu" then
      local okl, info = pcall(GetLitItemInfo, a1, a2)
      if okl and info ~= nil and info.menuObjectName == BattleBayDeluxe.Tournament.ROW_CAMPAIGN then
        local mode = BattleBayDeluxe.TournamentState.row_mode
        BattleBayDeluxe.TournamentState.row_mode = nil
        local t = mode == "tournament"
        if mode == nil then
          local ti = BBT_Info()
          t = ti.active == true or ti.ended == true
        end
        if t then
          funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
          local ok, err = pcall(BBT_EntryTournament)
          if not ok then
            BBT_Log("entry error", tostring(err))
          end
          return 1
        end
        VRFW_Param.Clear(BBT_MODE_P_GO_T)
      end
    end
    return decide(a1, a2, ...)
  end

  local back = OnBack
  function OnBack(a1, ...)
    -- 1.52.0: Back on the league hub's dashboard = «Salir» (its coroutine closes the overlay)
    if BattleBayDeluxe.TournamentState.open and (BBT_HubKey("back") or BBT_HubCalKey("back")) then
      return 1
    end
    if BattleBayDeluxe.TournamentState.open and BattleBayDeluxe.TournamentState.section then
      BattleBayDeluxe.TournamentState.section = false
      funcLuaCommand(1917805374, 202039849 --[[sy0006]])
      return 1
    end
    if BattleBayDeluxe.TournamentState.open then
      funcLuaCommand(1917805374, 202039849 --[[sy0006]])
      BBT_Close()
      return 1
    end
    return back(a1, ...)
  end

  -- the badge's retail setup (the Campaña record), then the running Torneo / Liga's next match over it
  local setup_layer = OnSetupLayer
  function OnSetupLayer(a1, a2, ...)
    local r = table.pack(setup_layer(a1, a2, ...))
    if a1 == BattleBayDeluxe.Tournament.BADGE then
      local ok, err = pcall(BBT_NextBadge, BBT_Info(), a2)
      if not ok then
        BBT_Log("badge error", tostring(err))
      end
    end
    return table.unpack(r, 1, r.n)
  end

  local fn = OnFunction
  function OnFunction(a1, a2, ...)
    if BattleBayDeluxe.TournamentState.open then
      -- 1.52.0: the league hub's side menu (Up / Down / L1 / R1; 1.58.0: six rows, no X key), a left click
      if BBT_HubKey("function", a1) or BBT_HubCalKey("function", a1) then
        return 1
      end
      -- 1.58.0: the arrows have their own ids (the dashboard's focus); elsewhere they turn the pages as L1 / R1
      if a1 == BattleBayDeluxe.Tournament.HUB.FN_LEFT then
        a1 = BattleBayDeluxe.Tournament.FN_PREV
      elseif a1 == BattleBayDeluxe.Tournament.HUB.FN_RIGHT then
        a1 = BattleBayDeluxe.Tournament.FN_NEXT
      end
      if a1 == BattleBayDeluxe.Tournament.FN_PREV then
        BBT_Turn(-1)
      elseif a1 == BattleBayDeluxe.Tournament.FN_NEXT then
        BBT_Turn(1)
      end
      return 1
    end
    return fn(a1, a2, ...)
  end

  local step = Step
  function Step(...)
    local r = { step(...) }
    local S = BattleBayDeluxe.TournamentState
    if S.setup_frames ~= nil then
      S.setup_frames = S.setup_frames + 1
      if S.setup_frames >= BBT_SETUP_FRAMES then
        S.setup_frames = nil
        local okc, errc = pcall(BBT_SetupCheck)
        if not okc then
          BBT_Logger().once("setup_check_error", "setup check error", tostring(errc))
        end
      end
    end
    if S.open and S.champ then
      pcall(BBT_ChampStep)
    end
    if S.open and S.focus_watch ~= nil then
      local okf, errf = pcall(BBT_FocusWatch)
      if not okf then
        S.focus_watch = nil
        BBT_Logger().once("overlay_keys_error", "overlay keys error", tostring(errf))
      end
    end
    -- 1.5.60: the group stage's own menu, opened after an earlier one closed
    local okg, errg = pcall(BBT_GroupsStep)
    if not okg then
      BBT_Logger().once("groups_menu_error", "groups menu error", tostring(errg))
    end
    -- the bracket screen (the tree page): opened after an earlier one closed
    local okt, errt = pcall(VRFW_Bracket.Step)
    if not okt then
      BBT_Logger().once("tree_menu_error", "bracket menu error", tostring(errt))
    end
    -- 1.5.33: a bracket layer set up after the bracket opened (bbt_hub.lua OnSetupLayer hid it): the page again
    if S.redraw then
      S.redraw = false
      if S.open and not S.champ then
        local ok, err = pcall(BBT_Draw, S.page)
        BBT_Log("late layer setup: page drawn again", S.page, ok and "" or tostring(err))
      end
    end
    if S.sync then
      S.sync_frames = S.sync_frames + 1
      local ok, done = pcall(BBT_Sync)
      if (ok and done) or S.sync_frames > 600 then
        S.sync = false
      end
    end
    -- the league hub's mouse / free cursor (before the coroutine: a click's action is taken this same Step)
    local okp, errp = pcall(BBT_HubPointerStep)
    if not okp then
      S.hub_ptr, S.hub_zones = nil, nil   -- off until the hub is drawn again
      BBT_Logger().once("hub_pointer_error", "hub pointer error", tostring(errp))
    end
    if S.co ~= nil then
      local ok, err = coroutine.resume(S.co)
      if not ok then
        BBT_Log("error", tostring(err))
      end
      if not ok or coroutine.status(S.co) == "dead" then
        S.co = nil
      end
    elseif S.step and not S.open then
      S.frames = S.frames + 1
      if S.frames > 600 then
        S.step = false
      elseif S.frames > 20 and funcLuaMenuCommand(102308320, BattleBayDeluxe.Tournament.LIST_MID) == true
        and funcLuaCommand(1215256347) ~= true then
        S.step = false
        local ok, err = pcall(BBT_DecideRow)
        if not ok then
          BBT_Log("top bar step error", tostring(err))
        end
      end
    elseif S.want and not S.open then
      S.frames = S.frames + 1
      -- 1.5.27 (owner: «Modos de juego» seen 1-2 s before the results): on a host with `cover` the screen stays black
      -- until the bracket is up (the wait was 20 Steps + the hub's own 0.5 s fade-in + its focus); then one fade-in
      local cover = BattleBayDeluxe.TournamentHost.cover == true
      if cover then
        funcLuaCommand(609722083 --[[fade black]], 1, 0)
      end
      if S.frames > 600 then
        S.want = false
        if cover then
          funcLuaCommand(609722083, 0, 0.3)
        end
      elseif S.frames > (cover and 2 or 20) and BattleBayDeluxe.TournamentHost.ready()
        and (cover or funcLuaCommand(1215256347) ~= true) then
        S.want = false
        local ok, err = pcall(BBT_Open, -1)
        if not ok then
          BBT_Log("overlay error", tostring(err))
        end
        if cover then
          funcLuaCommand(609722083, 0, 0.3)
          BBT_Log("results shown under the cover after", S.frames, "Steps")
        end
      end
    end
    return table.unpack(r)
  end
end
-- ===== EVT bb_tournament top wraps END =====

-- ===== EVT bb_tournament hub BEGIN =====
-- BattleBayDeluxe bb_tournament, «Modos de juego» (soccer_top_menu; Inazuma Fantasy's mode hub: graft modes_hub,
-- docs/game/modes/bb-tournament.md §0 1.5.18). Appended after bbt_common.lua + bbt_top.lua: the Torneo runs on THIS
-- screen (BattleBayDeluxe.TournamentHost below), never through the Battle Bay top menu (owner 2026-10-12: «not even for 0.6 s»).
--   * BBT_HubEntry(): the hub's «Torneo» tile (mh_hub.lua calls it in its decide coroutine; the top bar's Battle Bay →
--     Torneo is the title's «Modos de juego» request with the step mh_box.bb_tournament, which presses that tile):
--     no run = the team grid at once (the hub's own BB grid, EVT_MH_OpenBBGrid, with the tournament armed); a run =
--     the bracket with the Torneo window centred over it (bbt_top.lua BBT_EntryFlow).
--   * the bracket's layers are this menu's too (content\menus\bb_tournament.toml, soccer_top_menu patches); while it
--     is up the hub's tiles, group headers, utility boxes and help line are invisible and lose the focus; closing it
--     gives the focus back to the Torneo tile (EVT_MH_HostedBack).
--   * a tournament match started here: the hub's «BB match» mark (EVT_MH_MarkBBMatch) makes the engine reopen this
--     menu after the match; its OnInit syncs the result (bbt_top.lua) and the bracket opens on the round's results.
-- Without Inazuma Fantasy's hub (no EVT_MH_* globals) nothing here runs: the tile does not exist. Globals only;
-- nothing runs at chunk load.
BattleBayDeluxe = type(BattleBayDeluxe) == "table" and BattleBayDeluxe or {}
BattleBayDeluxe.TournamentHub = {
  KEY = "bb_tournament",                -- the hub tile's key (mh_hub.lua EVT_MH_BOXES)
  MODE = 534469705 --[[evt_mode_box]], DECO = 1293605056 --[[evt_mh_deco]], UTIL = 2237531969 --[[evt_comp_box]],
  NOTICE = 333699991, GUIDE = 1611500684 --[[mainmenu90_06_content_guide_line03]],
  GRID_VARIANT = 1455139087 --[[enjoy_team_select_menu_campaign]],
  ART = 1167254348 --[[mainmenu90_00_p1_background]],
}
BattleBayDeluxe.TournamentHost = {
  name = "soccer_top_menu", menu = 811496143,
  -- 1.5.22: the bracket's layers here are opened with the menu's group and shown / hidden by visibility only
  vis_only = true,
  -- 1.5.27: back from a tournament match the screen stays black until the bracket is up (no hub in between)
  cover = true,
  hide = { BattleBayDeluxe.TournamentHub.MODE, BattleBayDeluxe.TournamentHub.DECO, BattleBayDeluxe.TournamentHub.UTIL, BattleBayDeluxe.TournamentHub.GUIDE },
  -- 1.5.19 (owner: only the hub's character art, dimmed, behind the window): the hub's art layer
  -- (mainmenu90_00_p1_background) is closed under the bracket, as the Battle Bay top menu closes its own art
  close = { BattleBayDeluxe.TournamentHub.NOTICE, BattleBayDeluxe.TournamentHub.ART },
  lists = { BattleBayDeluxe.TournamentHub.MODE, BattleBayDeluxe.TournamentHub.UTIL },
  step = nil,
  -- 1.5.19 (owner: «Cuadro final» and a teal box over the top bar): the hub's header stays «Modos de juego» (the BB
  -- header type 30 does not fit this menu); the page title is not shown here
  title = function(_t) end,
  header = function() end,
  refocus = function()
    if type(EVT_MH_HostedBack) == "function" then
      EVT_MH_HostedBack(BattleBayDeluxe.TournamentHub.KEY)
    end
  end,
  ready = function()
    return funcLuaMenuCommand(102308320, BattleBayDeluxe.TournamentHub.MODE) == true
      or funcLuaMenuCommand(102308320, BattleBayDeluxe.TournamentHub.UTIL) == true
  end,
  open_grid = function()
    if type(EVT_MH_OpenBBGrid) == "function" then
      EVT_MH_OpenBBGrid(BattleBayDeluxe.TournamentHub.KEY, BattleBayDeluxe.TournamentHub.GRID_VARIANT)
    else
      BBT_Log("hub: no EVT_MH_OpenBBGrid (Inazuma Fantasy's hub too old): no grid")
    end
  end,
  before_match = function()
    if type(EVT_MH_MarkBBMatch) == "function" then
      EVT_MH_MarkBBMatch(BattleBayDeluxe.TournamentHub.KEY)
    end
  end,
  -- 1.5.58 (layer budget, docs/game/ui/menu-layer-limits.md §2.3): this menu's pools where they differ from the Battle
  -- Bay top menu's (BattleBayDeluxe.Tournament.N; the counts of content\menus\bb_tournament.toml, soccer_top_menu patches: change both
  -- together): no score-box pool, its boxes drawn on the connector pool at the box's draw priority (share); 64 texts
  -- (1.5.60: the same as the Battle Bay top menu; the group tables are drawn in their own menu, BBT_GroupsShow)
  pools = { box = 0, txt = 64 },
  share = { box = "line" },
}
for k, n in pairs(BattleBayDeluxe.TournamentHost.pools) do
  BattleBayDeluxe.Tournament.N[k] = n
end
BattleBayDeluxe.Tournament.SHARE = BattleBayDeluxe.TournamentHost.share

-- 1.5.22: every bracket layer (opened with this menu's group: content\menus\bb_tournament.toml) hidden and parked at
-- its setup, the anchor without the control focus until the bracket opens
do
  local setup = OnSetupLayer
  function OnSetupLayer(a1, a2, ...)
    local r = table.pack(setup(a1, a2, ...))
    local ours = a1 == BattleBayDeluxe.Tournament.ANCHOR
    for _, l in pairs(BattleBayDeluxe.Tournament.L) do
      if l == a1 then
        ours = true
      end
    end
    if ours then
      funcLuaMenuCommand(711242136, a1, a2 or 0, false)
      funcLuaMenuCommand(1389957207, a1, -4000, 4000, 0, a2 or 0)
      -- 1.5.33 (owner 2026-10-13, softlock): back from a tournament match the results bracket opens under the cover
      -- 2 Steps after the hub's focus, BEFORE this menu set up the anchor (log: anchor focus on at f7, off at f8 from
      -- here): the anchor lost its control focus and Aceptar / Esc / the mouse reached nothing. While the bracket is
      -- up the anchor keeps the focus, and a bracket layer set up late is drawn again (Step, bbt_top.lua)
      if BattleBayDeluxe.TournamentState.open then
        if a1 == BattleBayDeluxe.Tournament.ANCHOR then
          funcLuaMenuCommand(3518307824, a1, true)
          funcLuaMenuCommand(1778826357, a1, 0, true)
          BBT_Log("anchor set up while the bracket is open: focus kept")
        else
          BattleBayDeluxe.TournamentState.redraw = true
        end
      elseif a1 == BattleBayDeluxe.Tournament.ANCHOR then
        funcLuaMenuCommand(3518307824, a1, false)
      end
    end
    return table.unpack(r, 1, r.n)
  end
end

-- the hub's Torneo tile decided (runs in the hub's decide coroutine)
function BBT_HubEntry()
  funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
  BBT_Log("hub: Torneo tile")
  BBT_EntryTournament()
end
